export const MONSTER_COUNT_BY_REGION: Record<WorldRegionId, number> = REGIONAL_MONSTERS.reduce((acc, monster) => { acc[monster.regionId] = (acc[monster.regionId] || 0) + 1; return acc; }, {} as Record<WorldRegionId, number>);
export function getRegionalMonsterDefinition(id?: string | null): RegionalMonsterDefinition | undefined { return id ? REGIONAL_MONSTERS.find((m) => m.id === id) : undefined; }
export function getRegionalMonsterPool(regionId: WorldRegionId, layer: WorldMapLayer, terrain: HexTerrain, level: number, sectorId?: string) {
  const layerLevel = REGIONAL_MONSTERS.filter((m) => !m.tags.includes('DRAGONKIN_ONLY') && m.regionId === regionId && m.layers.includes(layer) && level >= m.minLevel - 3 && level <= m.maxLevel + 5);
  const terrainMatched = layerLevel.filter((m) => m.terrains.includes(terrain));
  if (!sectorId) return terrainMatched.length > 0 ? terrainMatched : layerLevel;
  const sectorTerrain = terrainMatched.filter((m) => m.sectorIds.includes(sectorId));
  if (sectorTerrain.length > 0) return sectorTerrain;
  // 특정 지하 지형의 전용 몬스터가 아직 적더라도 섹터 자체가 빈 인카운터가 되지 않도록
  // 같은 섹터에 배치된 몬스터를 2차 폴백으로 사용한다.
  const sectorAnyTerrain = layerLevel.filter((m) => m.sectorIds.includes(sectorId));
  if (sectorAnyTerrain.length > 0) return sectorAnyTerrain;
  return terrainMatched.length > 0 ? terrainMatched : layerLevel;
}
